// O no Compression valida pela EXTENSAO do binario e recusa '.docx'.
// docx e um zip -> renomeia o binario para .zip (mesmos bytes) antes de descompactar.
const item = $input.first();
const bin = item.binary || {};
const key = Object.keys(bin)[0];
if (key) {
  bin[key].fileName = 'contrato.zip';
  bin[key].fileExtension = 'zip';
  bin[key].mimeType = 'application/zip';
}
return [{ json: item.json, binary: bin }];

function decodeXml(s){ return (s||'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'"); }
function textoDosT(xml){ const m=(xml||'').match(/<w:t\b[^>]*>([\s\S]*?)<\/w:t>/g)||[]; return decodeXml(m.map(t=>t.replace(/<w:t\b[^>]*>/,'').replace(/<\/w:t>/,'')).join('')).replace(/\s+/g,' ').trim(); }
function attr(tag,name){ const m=(tag||'').match(new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'="([^"]*)"')); return m?decodeXml(m[1]):''; }
function trechoAncorado(documentXml,id){ if(!documentXml||id==='') return ''; const ini=documentXml.search(new RegExp('<w:commentRangeStart[^>]*w:id="'+id+'"[^>]*/?>')); const fim=documentXml.search(new RegExp('<w:commentRangeEnd[^>]*w:id="'+id+'"[^>]*/?>')); if(ini<0||fim<0||fim<=ini) return ''; return textoDosT(documentXml.slice(ini,fim)); }
function parseComentarios(commentsXml, documentXml){ if(!commentsXml) return []; const blocks=commentsXml.match(/<w:comment\b[\s\S]*?<\/w:comment>/g)||[]; return blocks.map(b=>{ const open=(b.match(/<w:comment\b[^>]*>/)||[''])[0]; const id=attr(open,'w:id'); return { id, autor: attr(open,'w:author')||'Revisor', data: attr(open,'w:date'), texto: textoDosT(b), trecho: trechoAncorado(documentXml,id) }; }).filter(c=>c.texto); }

let commentsXml = '', documentXml = '';
try {
  const bin = ($input.first() && $input.first().binary) || {};
  for (const key of Object.keys(bin)) {
    const fn = (bin[key] && bin[key].fileName ? bin[key].fileName : '').toString();
    try {
      if (fn.endsWith('comments.xml') && !fn.endsWith('commentsExtended.xml')) {
        commentsXml = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf8');
      } else if (fn.endsWith('word/document.xml') || fn.endsWith('/document.xml') || fn === 'document.xml') {
        documentXml = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf8');
      }
    } catch (e) { /* ignora arquivo ilegivel */ }
  }
} catch (e) { /* nao era zip (ex.: PDF) ou sem binarios */ }

let comentarios = [];
try { comentarios = parseComentarios(commentsXml, documentXml); } catch (e) { comentarios = []; }

return [{ json: { comentarios: comentarios } }];

// Junta o markdown das paginas retornadas pelo Mistral OCR
function pagesArr(resp) {
  const p = (resp && resp.pages) || [];
  return p.map(x => (x && x.markdown) ? x.markdown : '');
}
function joinPlain(resp) { return pagesArr(resp).join('\n\n').trim(); }

const body   = $('Webhook').item.json.body || {};
let modelo = {};
try { modelo = $('Buscar modelo').item.json || {}; } catch (e) { modelo = {}; }

// Cliente: paginas do OCR
const paginasCli = pagesArr($('OCR Cliente').item.json);
const paginasCliente = paginasCli.map((t, i) => ({ pagina: i + 1, texto: t }));
const totalPaginas = paginasCli.length;
// texto com marcadores de pagina -> permite o agente citar o campo "pagina"
const textoCliente = paginasCli.map((t, i) => `[[PAGINA ${i + 1}]]\n\n${t}`).join('\n\n').trim();

// Modelo: usa o cache (texto_extraido) quando existe; senao usa o OCR Modelo.
// O ramo do OCR pode nao ter executado nesta run (cache hit) -> try/catch.
let textoModelo = (modelo.texto_extraido && modelo.texto_extraido.trim())
  ? modelo.texto_extraido.trim()
  : '';
if (!textoModelo) {
  try { textoModelo = joinPlain($('OCR Modelo').item.json); } catch (e) { textoModelo = ''; }
}

if (!textoCliente) { throw new Error('OCR do contrato do cliente veio vazio.'); }
if (!textoModelo)  { throw new Error('Texto do modelo vazio (sem cache e sem OCR).'); }

// Comentarios extraidos do .docx (contexto adicional; pode estar vazio)
let comentarios = [];
try { const c = $('Extrair comentarios').item.json.comentarios; if (Array.isArray(c)) comentarios = c; } catch (e) { comentarios = []; }
const comentariosTexto = comentarios.length
  ? comentarios.map((c, i) => `(${i+1}) [${c.autor || 'Revisor'}]${c.trecho ? ` sobre "${c.trecho}"` : ''}: ${c.texto}`).join('\n')
  : '';

// Objecoes do cliente no portal da demanda juridica (vazio na analise manual)
const comentariosCliente = Array.isArray(body.comentariosCliente) ? body.comentariosCliente : [];
const comentariosClienteTexto = comentariosCliente.length
  ? comentariosCliente.map(c => `[id=${c.id}]${c.trecho ? ` sobre "${c.trecho}"` : ' (documento todo)'}: ${c.texto}${c.sugestao_redacao ? `
   Redacao proposta pelo cliente: "${c.sugestao_redacao}"` : ''}`).join('\n')
  : '';

return [{
  json: {
    origem:        body.origem || 'manual',
    comentariosCliente,
    comentariosClienteTexto,
    contratoId:    body.contratoId,
    tipoDocumento: body.tipoDocumento || '',
    modeloNome:    modelo.nome || body.modeloNome || 'Modelo Padrao BMS',
    totalPaginas,
    paginasCliente,
    textoModelo,
    textoCliente,
    comentarios,
    comentariosTexto
  }
}];

let raw = ($('Assistente Juridico').item.json.output || '').toString().trim();
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const _i = raw.indexOf('{'), _f = raw.lastIndexOf('}');
if (_i !== -1 && _f !== -1) raw = raw.slice(_i, _f + 1);
let dados;
try { dados = JSON.parse(raw); }
catch (e) { throw new Error('JSON invalido do agente: ' + e.message + '\n' + raw.slice(0, 400)); }

const ctx = $('Montar contexto').item.json || {};
const modeloNome = ctx.modeloNome || 'Modelo Padrao BMS';
const totalPaginas = ctx.totalPaginas || null;
const paginasCliente = Array.isArray(ctx.paginasCliente) ? ctx.paginasCliente : [];

function normSev(s){ const k=(s||'').toString().trim().toUpperCase();
  if(k.indexOf('CRIT')===0||k.indexOf('CRÍT')===0) return 'CRÍTICA';
  if(k==='ALTA') return 'ALTA';
  if(k==='MEDIA'||k==='MÉDIA') return 'MÉDIA';
  if(k==='BAIXA') return 'BAIXA';
  return 'MÉDIA'; }
function esc(s){ return (s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function bq(s){ return (s==null?'':String(s)).split('\n').map(l=>'> '+l).join('\n'); }
const SEVR = { 'CRÍTICA':0, 'ALTA':1, 'MÉDIA':2, 'BAIXA':3 };

const inAch = Array.isArray(dados.achados) ? dados.achados : [];
const conformesIn = Array.isArray(dados.conformes) ? dados.conformes : [];

const achados = inAch.map((d, i) => ({
  id: 'p' + (i + 1),
  num: i + 1,
  tipo: d.tipo === 'ausente' ? 'ausente' : 'divergencia',
  severidade: normSev(d.severidade),
  impacto: d.impacto || '',
  titulo: d.titulo || d.tema || 'Divergência',
  clausula: d.clausula || '',
  clausula_id: d.clausula_id || '',
  pagina: (d.pagina === 0 || d.pagina) ? d.pagina : null,
  trecho_modelo: d.trecho_modelo || '',
  trecho_cliente: d.trecho_cliente || '',
  trecho_exato: d.trecho_exato || '',
  ancora_anterior: d.ancora_anterior || '',
  ancora_posterior: d.ancora_posterior || '',
  diferenca: d.diferenca || '',
  sugestao: d.sugestao || d.sugestao_redacao || '',
  racional: d.racional || ''
})).sort((a, b) => (SEVR[a.severidade] ?? 9) - (SEVR[b.severidade] ?? 9)).map((a, i) => ({ ...a, num: i + 1 }));

// Avaliacao das objecoes do cliente (demanda juridica). So aceita ids que foram enviados.
const REC = { aceitar: 'aceitar', negociar: 'negociar', recusar: 'recusar' };
const idsEnviados = new Set((ctx.comentariosCliente || []).map(c => String(c.id)));
const avaliacao_comentarios = (Array.isArray(dados.avaliacao_comentarios) ? dados.avaliacao_comentarios : [])
  .filter(a => a && idsEnviados.has(String(a.comentario_id)))
  .map(a => ({
    comentario_id: String(a.comentario_id),
    recomendacao: REC[(a.recomendacao || '').toString().trim().toLowerCase()] || 'negociar',
    severidade: normSev(a.severidade),
    impacto: a.impacto || '',
    clausula_id: a.clausula_id || '',
    racional: a.racional || '',
    redacao_sugerida: a.redacao_sugerida || ''
  }));

const conformes = conformesIn.map(c => ({ clausula: c.clausula || '', clausula_id: c.clausula_id || '' }));

const contadores = { critica:0, alta:0, media:0, baixa:0, divergencia:0, ausente:0, conforme: conformes.length };
achados.forEach(a => {
  if (a.severidade === 'CRÍTICA') contadores.critica++;
  else if (a.severidade === 'ALTA') contadores.alta++;
  else if (a.severidade === 'MÉDIA') contadores.media++;
  else if (a.severidade === 'BAIXA') contadores.baixa++;
  if (a.tipo === 'ausente') contadores.ausente++; else contadores.divergencia++;
});

// ---- ADERENCIA DETERMINISTICA ----
// Proporcao de aderencia ponderada por severidade.
// Cada clausula avaliada vale 1. Conforme = 100% aderente.
// Cada achado "perde" aderencia conforme a gravidade (PEN). Ausente pesa +EXTRA.
// Ajuste os pesos aqui se o juridico quiser calibrar.
const PEN = { 'CRÍTICA': 1.0, 'ALTA': 0.7, 'MÉDIA': 0.4, 'BAIXA': 0.2 };
const EXTRA_AUSENTE = 0.1;
const totalClausulas = conformes.length + achados.length;
let aderentes = conformes.length; // conformes contam como 1 (100%)
achados.forEach(a => {
  let p = (PEN[a.severidade] != null) ? PEN[a.severidade] : 0.4;
  if (a.tipo === 'ausente') p = Math.min(1, p + EXTRA_AUSENTE);
  aderentes += (1 - p);
});
let aderenciaCalc = totalClausulas > 0 ? Math.round(100 * aderentes / totalClausulas) : null;
if (aderenciaCalc != null) aderenciaCalc = Math.max(0, Math.min(100, aderenciaCalc));

// IA como FALLBACK (so entra se nao deu pra calcular)
let aderenciaIa = parseInt(dados.aderencia, 10);
aderenciaIa = isNaN(aderenciaIa) ? null : Math.max(0, Math.min(100, aderenciaIa));

const aderencia = (aderenciaCalc != null) ? aderenciaCalc : aderenciaIa;
const aderenciaOrigem = (aderenciaCalc != null) ? 'deterministica' : (aderenciaIa != null ? 'ia' : 'indefinida');

const analise_json = {
  versao: 2,
  gerado_em: new Date().toISOString(),
  modelo_nome: modeloNome,
  resumo: dados.resumo || '',
  aderencia: aderencia,
  aderencia_origem: aderenciaOrigem,
  aderencia_ia: aderenciaIa,
  total_paginas: totalPaginas,
  contadores: contadores,
  achados: achados,
  conformes: conformes,
  comentarios: Array.isArray(ctx.comentarios) ? ctx.comentarios : [],
  origem: ctx.origem || 'manual',
  comentarios_cliente: Array.isArray(ctx.comentariosCliente) ? ctx.comentariosCliente : [],
  avaliacao_comentarios: avaliacao_comentarios,
  documento: paginasCliente
};

// ---- Markdown (analise_ia / compat + fonte do PDF) ----
const md = [];
md.push(`## Analise Comparativa de Contrato — ${modeloNome}`);
if (analise_json.resumo) md.push('', `> ${analise_json.resumo}` + (aderencia!=null?`  (aderencia ${aderencia}%)`:''));
md.push('', '## Achados');
if (!achados.length) md.push('', '_Nenhuma divergencia relevante identificada._');
achados.forEach(a => {
  md.push('', `### ${a.num}. ${a.titulo}${a.clausula?' — '+a.clausula:''}`);
  md.push('', `**Tipo:** ${a.tipo} · **Severidade:** ${a.severidade} · **Impacto:** ${a.impacto||'N/D'}${a.pagina!=null?' · **Pag.** '+a.pagina:''}`);
  md.push('', '**Modelo Padrao BMS:**', '', bq(a.trecho_modelo || '(nao consta no modelo)'));
  md.push('', '**Contrato do Cliente:**', '', bq(a.trecho_cliente || '(nao consta no contrato do cliente)'));
  if (a.diferenca) md.push('', `**Diferenca:** ${a.diferenca}`);
  if (a.sugestao) md.push('', bq(`Sugestao de Redacao (Texto Final):\n"${a.sugestao}"` + (a.racional?`\n\nRacional: ${a.racional}`:'')));
});
if (avaliacao_comentarios.length) {
  const porId = new Map((ctx.comentariosCliente || []).map(c => [String(c.id), c]));
  md.push('', '## Objecoes do cliente');
  avaliacao_comentarios.forEach((a, i) => {
    const c = porId.get(a.comentario_id) || {};
    md.push('', `### ${i + 1}. ${a.recomendacao.toUpperCase()} · ${a.severidade}${a.clausula_id ? ' · Clausula ' + a.clausula_id : ''}`);
    if (c.trecho) md.push('', bq(c.trecho));
    md.push('', `**Pedido do cliente:** ${c.texto || ''}`);
    if (a.racional) md.push('', `**Racional:** ${a.racional}`);
    if (a.redacao_sugerida) md.push('', bq(`Redacao sugerida:
"${a.redacao_sugerida}"`));
  });
}
if (conformes.length) { md.push('', '## Clausulas conformes'); conformes.forEach(c => md.push('', `- ${c.clausula}${c.clausula_id?' ('+c.clausula_id+')':''}`)); }
md.push('', '> *Este relatorio tem carater informativo e nao substitui consulta juridica individualizada.*');
const analise_md = md.join('\n');

// ---- HTML (PDF) ----
function sevColor(s){ const k=(s||'').toUpperCase(); if(k.indexOf('CRÍT')===0||k.indexOf('CRIT')===0)return '#C0392B'; if(k==='ALTA')return '#E8620E'; if(k==='MÉDIA'||k==='MEDIA')return '#C08A00'; return '#1E8E5A'; }
let blocos='';
achados.forEach(a => {
  blocos += `<section class="d"><h3>${a.num}. ${esc(a.titulo)}${a.clausula?' — '+esc(a.clausula):''}</h3><p class="m"><span class="b" style="background:${sevColor(a.severidade)}">${esc(a.severidade)}</span> <b>Impacto:</b> ${esc(a.impacto||'N/D')}${a.pagina!=null?' · <b>Pag.</b> '+esc(a.pagina):''} · <b>Tipo:</b> ${esc(a.tipo)}</p><p class="l">Modelo Padrao BMS:</p><blockquote>${esc(a.trecho_modelo||'(nao consta no modelo)').replace(/\n/g,'<br>')}</blockquote><p class="l">Contrato do Cliente:</p><blockquote>${esc(a.trecho_cliente||'(nao consta no contrato do cliente)').replace(/\n/g,'<br>')}</blockquote>${a.diferenca?`<p><b>Diferenca:</b> ${esc(a.diferenca)}</p>`:''}${a.sugestao?`<div class="s"><p class="st">Sugestao de Redacao (Texto Final)</p><p class="sc">"${esc(a.sugestao).replace(/\n/g,'<br>')}"</p>${a.racional?`<p class="sr"><i>Racional: ${esc(a.racional)}</i></p>`:''}</div>`:''}</section>`;
});
const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>
 body{font-family:Arial,Helvetica,sans-serif;line-height:1.45;color:#111;margin:28px}
 h1{color:#0F2A47;font-size:20pt;margin:0 0 2px} h2{color:#0F2A47;font-size:14pt;margin:18px 0 6px;border-bottom:2px solid #E8620E;padding-bottom:3px}
 h3{font-size:12.5pt;margin:16px 0 4px;color:#0F2A47}
 .m{margin:2px 0 8px;font-size:9.5pt;color:#444} .b{color:#fff;padding:2px 8px;border-radius:10px;font-size:8.5pt;font-weight:700}
 .l{font-weight:700;margin:8px 0 2px;font-size:10pt}
 blockquote{border-left:3px solid #ccc;background:#F2F5FA;margin:0;padding:8px 12px;font-size:10pt}
 .s{border-left:4px solid #E8620E;background:#FFF7EE;padding:10px 12px;margin:10px 0;border-radius:4px}
 .st{font-weight:700;color:#C24E08;margin:0 0 4px} .sc{margin:0;font-size:10.5pt} .sr{margin:6px 0 0;color:#666;font-size:9.5pt}
 .exec{background:#F2F5FA;border-left:4px solid #0F2A47;padding:10px 14px;margin:10px 0;font-size:10.5pt}
</style></head><body>
 <h1>Analise Comparativa de Contrato</h1>
 <p style="color:#555;margin:0 0 6px">${esc(modeloNome)}${aderencia!=null?` · aderencia ${aderencia}%`:''}</p>
 ${analise_json.resumo?`<div class="exec">${esc(analise_json.resumo)}</div>`:''}
 ${avaliacao_comentarios.length ? `<h2>Objecoes do cliente</h2>` + avaliacao_comentarios.map((a, i) => { const c = (ctx.comentariosCliente || []).find(x => String(x.id) === a.comentario_id) || {}; return `<section class="d"><h3>${i + 1}. ${esc(a.recomendacao.toUpperCase())}${a.clausula_id ? ' — Clausula ' + esc(a.clausula_id) : ''}</h3><p class="m"><span class="b" style="background:${sevColor(a.severidade)}">${esc(a.severidade)}</span> <b>Impacto:</b> ${esc(a.impacto || 'N/D')}</p>${c.trecho ? `<blockquote>${esc(c.trecho)}</blockquote>` : ''}<p><b>Pedido do cliente:</b> ${esc(c.texto || '')}</p>${a.racional ? `<p><b>Racional:</b> ${esc(a.racional)}</p>` : ''}${a.redacao_sugerida ? `<div class="s"><p class="st">Redacao sugerida</p><p class="sc">"${esc(a.redacao_sugerida).replace(/\n/g, '<br>')}"</p></div>` : ''}</section>`; }).join('') : ''}
 <h2>Achados</h2>
 ${blocos || '<p>Nenhuma divergencia relevante identificada.</p>'}
 <p style="margin-top:20px;color:#666;font-size:9pt;font-style:italic">Este relatorio tem carater informativo e nao substitui consulta juridica individualizada.</p>
</body></html>`;

return [{ json: { analise_json: analise_json, analise_md: analise_md, html: html, aderencia: aderencia, total_paginas: totalPaginas } }];

